/*!
 * wega-music-rory.js - RORY'S CHALLENGE add-on for the Wega's Challenge music pack.
 * Load AFTER wega-music.js and BEFORE the game module. It registers a "rory" track with
 * WegaMusic so WegaMusic.init() decodes it with the others and WegaMusic.play("rory") works.
 * RORY'S CHALLENGE (a game mode) is synced to this song from the first beat to the last: its timer is the song,
 * every section brings in its own enemies and its own look, and once the song is over the drop loops (OVERTIME)
 * while Shoebench comes for you. Without this file the mode still runs on the same clock, just silently.
 * Measured from the audio: 145 BPM, first downbeat at 0.208 s, sections on 8-bar phrases, the music ends on
 * bar 168 (278.28 s); the overtime loop is 16 bars of the drop, cut at click-free samples.
 * Track: RORY'S CHALLENGE - supplied by the player.
 */
(function (global) {
  "use strict";
  var D = global.WEGA_MUSIC_DATA, W = global.WegaMusic;
  if (!D || !W) { if (global.console) console.warn("[wega-music-rory] load wega-music.js first"); return; }
  D.rory = {
    title: "RORY'S CHALLENGE (Rory's Challenge Theme)",
    credit: "RORY'S CHALLENGE - supplied by the player",
    duration: 281.25,
    loopStart: 0.0,
    loopEnd: 281.2,
    gain: 0.62,
    bpm: 145,
    beat0: 0.208,
    end: 278.28,
    overtime: [178.96952, 205.44887],
    src: "data:audio/mpeg;base64,"
  };
  if (W.tracks.indexOf("rory") < 0) W.tracks.push("rory");
})(typeof window !== "undefined" ? window : globalThis);
